<div class="d-flex justify-content-between align-items-start gap-3 mb-4"><div><p class="text-body-secondary mb-1">Kundeninfo für <?= htmlspecialchars((string) $customer->name) ?></p><h1 class="h3 mb-0"><?= htmlspecialchars((string) $info->title) ?></h1></div><div class="d-flex gap-2"><a class="btn btn-outline-secondary" href="<?= htmlspecialchars(url_for('kunden/' . (int) $customer->id . '/infos'), ENT_QUOTES) ?>">Alle Kundeninfos</a><?php if ($canManage): ?><a class="btn btn-outline-primary" href="<?= htmlspecialchars(url_for('kunden/' . (int) $customer->id . '/infos/' . (int) $info->id . '/bearbeiten'), ENT_QUOTES) ?>">Bearbeiten</a><?php endif; ?></div></div>
<article class="card shadow-sm"><div class="card-body customer-info-markdown"><?= $markdown ?><?php if (trim((string) $info->file_name) !== ''): ?><hr><?php if (str_starts_with((string) $info->file_mime, 'image/')): ?><img class="img-fluid rounded border mb-3" src="<?= htmlspecialchars(url_for('kundeninfos/' . (int) $info->id . '/datei'), ENT_QUOTES) ?>" alt="<?= htmlspecialchars((string) $info->title) ?>"><?php endif; ?><div><a class="btn btn-outline-primary" href="<?= htmlspecialchars(url_for('kundeninfos/' . (int) $info->id . '/datei'), ENT_QUOTES) ?>" target="_blank" rel="noopener"><i class="fa-solid fa-file-arrow-down me-1" aria-hidden="true"></i><?= htmlspecialchars((string) $info->file_name) ?></a></div><?php endif; ?></div></article>
